#include "../core/internal.h"

void ls_transport_register(ls_transport_backend_t *transport){if(!transport||!transport->send)return;for(size_t i=0;i<ls_runtime.transport_count;i++)if(ls_runtime.transports[i]==transport)return;if(ls_runtime.transport_count<LS_MAX_TRANSPORTS)ls_runtime.transports[ls_runtime.transport_count++]=transport;}
void ls_transport_clear(void){ls_runtime.transport_count=0;}
ls_transport_backend_t *ls_transport_select(ls_priority_t priority,size_t event_size){ls_transport_backend_t *best=0;int best_score=-2147483647;for(size_t i=0;i<ls_runtime.transport_count;i++){ls_transport_backend_t *transport=ls_runtime.transports[i];if(!transport||!transport->send||(transport->available&&!transport->available(transport->context)))continue;size_t mtu=transport->max_payload?transport->max_payload(transport->context):event_size;if(mtu<event_size&&(!(transport->capabilities&LS_TRANSPORT_FRAGMENT)||!transport->send_fragment))continue;int score=transport->priority*1000;if(priority>=LS_PRIORITY_WARNING){score-=(int)transport->energy_cost;score-=(int)transport->monetary_cost*2;}if(transport->capabilities&LS_TRANSPORT_ACK)score+=20;if(score>best_score){best=transport;best_score=score;}}return best;}
ls_result_t ls_transport_send(ls_transport_backend_t *transport,uint32_t event_id,const uint8_t *data,size_t length){if(!transport||!data||!length)return LS_EINVAL;size_t mtu=transport->max_payload?transport->max_payload(transport->context):length;if(!mtu)return LS_EINVAL;if(length<=mtu)return transport->send(transport->context,data,length);if(!(transport->capabilities&LS_TRANSPORT_FRAGMENT)||!transport->send_fragment)return LS_ENOTSUP;size_t count=(length+mtu-1u)/mtu;if(count>65535u)return LS_EOVERFLOW;for(size_t index=0;index<count;index++){size_t offset=index*mtu,fragment_length=length-offset;if(fragment_length>mtu)fragment_length=mtu;ls_result_t result=transport->send_fragment(transport->context,event_id,(uint16_t)index,(uint16_t)count,data+offset,fragment_length,ls_crc32(data+offset,fragment_length));if(result!=LS_OK)return result;}return LS_OK;}
